svg.script:
(() => {
  const root = document.documentElement;
  const topics = {
    "mmf":        { "label": "磁动势 F = NI", "detail": "线圈电流与匝数的乘积是驱动磁通的源，对应电路中的电动势。", "animate": false },
    "flux":       { "label": "磁通 Φ", "detail": "磁通沿磁路闭合流动，大小由磁动势与磁路磁阻共同决定。", "animate": true },
    "reluctance": { "label": "磁阻 Rm = l/(μA)", "detail": "磁路越长、截面积越小、磁导率越低，磁阻越大；气隙往往主导总磁阻。", "animate": false },
    "result":     { "label": "磁路欧姆定律", "detail": "Φ = F / Rm：与电路欧姆定律 I = U / R 一一对应，是估算磁通的出发点。", "animate": false }
  };
  const topicNodes = [...root.querySelectorAll('[data-topic]')];
  const titleNode = root.getElementById('interaction-title');
  const detailNode = root.getElementById('interaction-detail');
  const DRAG_THRESHOLD = 8;
  let pinnedTopic = null;
  let pointerGesture = null;

  function renderTopic(key, animate = false) {
    const topic = topics[key];
    topicNodes.forEach((node) => {
      const active = node.dataset.topic === key;
      node.classList.toggle('is-active', Boolean(key) && active);
      node.classList.toggle('is-dimmed', Boolean(key) && !active);
    });
    if (!topic) {
      titleNode.textContent = '交互提示';
      detailNode.textContent = '悬停预览，轻点锁定；拖动后松开不触发；按 Esc 或轻点空白取消。';
      return;
    }
    titleNode.textContent = topic.label;
    detailNode.textContent = topic.detail;
    if (animate && topic.animate) {
      topicNodes
        .filter((node) => node.dataset.topic === key)
        .forEach((node) => {
          node.classList.remove('flow-once');
          void node.getBoundingClientRect();
          node.classList.add('flow-once');
          window.setTimeout(() => node.classList.remove('flow-once'), 1250);
        });
    }
  }

  function togglePinnedTopic(key) {
    pinnedTopic = pinnedTopic === key ? null : key;
    renderTopic(pinnedTopic, true);
  }

  function beginPointerGesture(event, node) {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    pointerGesture = {
      pointerId: event.pointerId,
      node,
      startX: event.clientX,
      startY: event.clientY,
      moved: false
    };
    node.setPointerCapture(event.pointerId);
  }

  function movePointerGesture(event) {
    if (!pointerGesture || pointerGesture.pointerId !== event.pointerId) return;
    const dx = event.clientX - pointerGesture.startX;
    const dy = event.clientY - pointerGesture.startY;
    if (Math.hypot(dx, dy) > DRAG_THRESHOLD) pointerGesture.moved = true;
  }

  function finishPointerGesture(event, cancelled = false) {
    if (!pointerGesture || pointerGesture.pointerId !== event.pointerId) return;
    const gesture = pointerGesture;
    pointerGesture = null;
    if (gesture.node.hasPointerCapture(event.pointerId)) {
      gesture.node.releasePointerCapture(event.pointerId);
    }
    if (!cancelled && !gesture.moved) togglePinnedTopic(gesture.node.dataset.topic);
  }

  topicNodes.forEach((node) => {
    node.addEventListener('pointerenter', (event) => {
      if (event.pointerType === 'mouse' && !pinnedTopic) renderTopic(node.dataset.topic);
    });
    node.addEventListener('pointerleave', (event) => {
      if (event.pointerType === 'mouse' && !pinnedTopic) renderTopic(null);
    });
    node.addEventListener('pointerdown', (event) => {
      event.stopPropagation();
      beginPointerGesture(event, node);
    });
    node.addEventListener('pointermove', movePointerGesture);
    node.addEventListener('pointerup', (event) => {
      event.stopPropagation();
      finishPointerGesture(event);
    });
    node.addEventListener('pointercancel', (event) => finishPointerGesture(event, true));
    node.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        togglePinnedTopic(node.dataset.topic);
      }
    });
  });
  root.addEventListener('pointerup', (event) => {
    const target = event.target;
    if (!(target instanceof Element) || !target.closest('[data-topic]')) {
      pinnedTopic = null;
      renderTopic(null);
    }
  });
  root.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') { pinnedTopic = null; renderTopic(null); }
  });
  renderTopic(null);
})();
